css:
/* 极简科技：昼夜双版（:root 为日间基线，[data-reader-theme="night"] 覆盖夜景）；正文区占页高 80%+（蓝图硬约束①） */
:root{
  --mt-bg:#fbfbfc; --mt-fg:#20232a; --mt-dim:#787f8c;
  --mt-accent:#0891b2; --mt-line:rgba(8,145,178,.26);
}
[data-reader-theme="night"]{
  --mt-bg:#0d0f13; --mt-fg:#e7eaf0; --mt-dim:#868e9c;
  --mt-accent:#22d3ee; --mt-line:rgba(34,211,238,.30);
}
html,body{margin:0;padding:0;background:var(--mt-bg);color:var(--mt-fg);
  font-family:-apple-system,"Noto Sans CJK SC","Source Han Sans SC",sans-serif;
  font-size:var(--md-font-size,18px);line-height:var(--md-line-height,1.85);}
body::before{content:"";position:absolute;inset:.55em;pointer-events:none;
  border:1px solid var(--mt-line);
  -webkit-mask-image:linear-gradient(160deg,#000,transparent 46%,#000);mask-image:linear-gradient(160deg,#000,transparent 46%,#000);}
.mt-head{position:relative;display:flex;justify-content:space-between;align-items:baseline;gap:.6em;
  padding:1.05em 1.55em .5em;font-size:.76em;letter-spacing:.24em;color:var(--mt-dim);text-transform:uppercase;}
.mt-chapter{max-width:74%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}
.mt-pct{color:var(--mt-accent);font-variant-numeric:tabular-nums;letter-spacing:.06em;}
.mt-bar{position:relative;height:1px;margin:.15em 1.55em 0;background:var(--mt-line);}
.mt-bar-fill{position:absolute;left:0;top:-1px;height:3px;width:calc(var(--rp-percent,0) * 1%);
  max-width:100%;background:var(--mt-accent);}
.mt-body{position:relative;padding:1em 1.55em 0;}
.mt-body .reader-chapter-title{margin:0 0 .85em;font-size:1.42em;font-weight:600;letter-spacing:.01em;}
.mt-body .reader-chapter-title::after{content:"";display:block;width:2.2em;height:2px;margin-top:.42em;background:var(--mt-accent);}
.mt-body .reader-paragraph{margin:0 0 1em;text-indent:2em;}
.mt-body p{margin:0 0 1em;}
.mt-body a{color:var(--mt-accent);text-decoration:none;border-bottom:1px solid var(--mt-line);}
.mt-body blockquote{margin:0 0 1.05em;padding:.45em 0 .45em 1em;border-left:1px solid var(--mt-accent);color:var(--mt-dim);}
.mt-body code{background:rgba(127,127,127,.14);padding:.13em .34em;border-radius:3px;}
.mt-body pre{background:rgba(127,127,127,.10);padding:.8em;border-radius:4px;overflow-x:auto;border:1px solid var(--mt-line);}
.mt-body table{width:100%;border-collapse:collapse;}
.mt-body th,.mt-body td{border:1px solid var(--mt-line);padding:.34em .55em;}
.mt-foot{position:relative;display:flex;justify-content:space-between;align-items:center;gap:.8em;
  padding:.5em 1.55em .95em;font-size:.7em;letter-spacing:.2em;color:var(--mt-dim);
  font-variant-numeric:tabular-nums;text-transform:uppercase;}
.mt-foot-mark{opacity:.55;letter-spacing:.34em;}
@media (prefers-reduced-motion:reduce){.mt-bar-fill{transition:none;}}
